func TestB3RenderOutlineViewRefusesLanguageThatIsNotUTF8(t *testing.T) {
	_, err := RenderOutlineView(nil, false, false, "\xff")
	if failure, ok := err.(*liberrors.CRUDUIValueError); !ok || failure.Kind() != "invalid_text" {
		t.Fatalf("B-3: %#v", err)
	}
}

func TestB4RenderOutlineViewInvalidFormInput(t *testing.T) {
	_, err := RenderOutlineView([]*json.Value{}, false, false, "xx")
	failure, ok := err.(*liberrors.FormError)
	if !ok || failure.Kind() != "invalid_form_input" {
		t.Fatalf("B-4: %#v", err)
	}
	var category *liberrors.CRUDUIValueError
	if !errors.As(err, &category) {
		t.Fatalf("E-2: %#v is no error of its category", err)
	}
	if _, ok := failure.Status(); ok {
		t.Fatalf("B-4: the status of %#v", err)
	}
	if _, ok := failure.Errno(); ok {
		t.Fatalf("B-4: the errno of %#v", err)
	}
}

